const u=[{id:"F01",title:"Sahih al-Bukhari 1 · Taten und Absichten",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"Umar ibn al-Khattab überliefert die Lehre des Propheten über Taten und Absichten.",limitation:"Religiöse Quelle, keine empirische Studie. ODAs Übung für Alltagsaufgaben ist eine Auslegung, weder der Wortlaut des Hadiths noch ein religiöses Urteil. Eine App kann Aufrichtigkeit oder göttlichen Lohn nicht beurteilen."},{id:"F02",title:"Sahih al-Bukhari 6491 · Beabsichtigte und ausgeführte Taten",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"Die von Ibn Abbas überlieferte Passage beschreibt, wie beabsichtigte und ausgeführte gute und schlechte Taten verzeichnet werden.",limitation:"Ihre theologischen Einzelheiten sind kein psychologisches Gesetz. ODAs Aufzeichnungen über Vorbereitung und Handeln beschreiben Verhalten. Sie können nicht über religiösen Lohn urteilen."},{id:"F03",title:"Der Koran · Al Imran 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Beratung, Entschluss und Vertrauen kommen in diesem Vers gemeinsam vor.",limitation:"ODA nutzt ihn als Anregung für freiwilliges Nachdenken im Alltag. Daraus folgt keine allgemeine Reihenfolge, nach der Vertrauen erst nach Vorbereitung beginnt. Die Übung bietet weder eine vollständige Auslegung noch ein garantiertes Ergebnis."},{id:"F07",title:"Sunan Abi Dawud 4811 · Menschen danken",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"Die von Abu Hurayrah überlieferte Lehre verbindet Dank an Menschen mit Dank an Allah. Der Eintrag zeigt die Einstufung „sahih“ durch al-Albani.",limitation:"Religiöse Lehre, kein Beleg psychologischer Wirksamkeit. Die konkrete Dankesvorlage ist ODAs Anpassung. Quellen zu prüfen ist keine neue religiöse Beglaubigung und verlangt keinen unsicheren Kontakt."},{id:"F08",title:"Der Koran · Al-Sharh 94:5–6",url:"https://quran.com/94/5-6",type:"religious",finding:"Erleichterung neben Schwierigkeiten bietet eine religiöse Quelle der Hoffnung.",limitation:"Keine Garantie, dass deine Schwierigkeit heute oder bis zu einem gewählten Datum endet. ODAs Bitte um Unterstützung ist eine praktische Anpassung, kein klinischer Effekt und keine vollständige Auslegung."},{id:"F11",title:"Sahih al-Bukhari 6464 · Kleine regelmäßige Taten und Maßhalten",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Aischa überliefert eine Lehre, die kleine regelmäßige Taten und Maßhalten betont.",limitation:"Die vollständige Passage betrifft auch Taten und Heil. Eine Übungsserie in der App misst weder Glauben noch Heil. Der begrenzte Plan für eine hilfreiche Handlung ist ODAs Anpassung."},{id:"F13",title:"Ano und Vasconcelles · 2005 · Religiöse Bewältigung und Anpassung",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"49 überwiegend beobachtende Studien zeigten Zusammenhänge zwischen religiöser Bewältigung und Anpassung. Tabelle 5 enthält zusammengefasste Fisher-z-Werte: 0,33 [0,30; 0,35] für positive Bewältigung/positive Anpassung und 0,22 [0,19; 0,24] für negative Bewältigung/negative Anpassung.",limitation:"Keine ursprünglichen Korrelationswerte und kein Kausalitätsbeleg. Unter 8.115 Personen mit angegebener Religionszugehörigkeit waren 57% protestantisch und 28% katholisch. Andere Einflüsse, Selbstauskünfte und begrenzte Übertragbarkeit auf islamische Praxis bleiben Einschränkungen. Forschungskategorien urteilen nicht über dich."},{id:"F14",title:"Kirca und andere · 2023 · Ausgedrückte Dankbarkeit und Wohlbefinden",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"In 23 Studien mit 25 Stichproben zeigte ausgedrückte Dankbarkeit gegenüber neutralen Vergleichen einen kleinen durchschnittlichen Nutzen für das Wohlbefinden: g = 0,22, 95%-Konfidenzintervall [0,11; 0,33]. Gegenüber anderen Aktivitäten für Wohlbefinden: g = 0,12 [−0,02; 0,26].",limitation:"Keine belegte Überlegenheit gegenüber aktiven Vergleichen oder Gleichwertigkeit mit Therapie. Überwiegend nichtklinische Stichproben. Der Artikel nennt widersprüchliche Teilnehmerzahlen; beide bleiben ungenutzt. Kein Beleg religiöser Wirksamkeit, keine Kontaktpflicht oder Garantie persönlichen Nutzens."},{id:"F15",title:"Choi und andere · 2025 · Dankbarkeit in verschiedenen Kulturen",url:"https://www.pnas.org/doi/10.1073/pnas.2425193122",type:"research",finding:"145 Artikel und 163 Stichproben aus 28 Ländern zeigten einen kleinen durchschnittlichen Effekt von Dankbarkeitsübungen auf Wohlbefinden: g = 0,19, 95%-Konfidenzintervall [0,15; 0,22]. Das Vorhersageintervall für eine künftige Studie betrug [−0,21; 0,59].",limitation:"Überwiegend nichtklinische Stichproben mit unterschiedlichen Vorgehensweisen. Effekte variieren; das Vorhersageintervall enthält null. Das bestätigt weder einen einzelnen privaten Satz noch deine persönliche Reaktion oder eine Überlegenheit islamischer Dankbarkeit."},{id:"F16",title:"Curry und andere · 2018 · Freundlichkeit und Wohlbefinden der helfenden Person",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"In 27 Studien mit 4.045 Personen zeigten freundliche Handlungen einen bescheidenen durchschnittlichen Nutzen für das Wohlbefinden der helfenden Person: δ = 0,28, 95%-Konfidenzintervall [0,16; 0,41].",limitation:"Unterschiedliche, überwiegend nichtklinische Studien. Keine Garantie für jede helfende oder empfangende Person, kein Behandlungseffekt und kein Maß religiösen Lohns. Keine Bestätigung unbegrenzter Selbstaufopferung. Nicht entdeckte Verzerrungen oder Einflussfaktoren sind damit nicht ausgeschlossen."},{id:"F18",title:"Nelson und andere · 2016 · Versuch zu hilfreichem Verhalten",url:"https://sonjalyubomirsky.com/wp-content/uploads/2024/03/Nelson-Layous-Cole-Lyubomirsky-2016.pdf",type:"research",finding:"Eine Gruppe sollte vier Wochen lang an einem Tag pro Woche drei freundliche Handlungen für andere tun. Zwei Wochen danach folgte eine Messung. Für zusammengefasste prosoziale Gruppen gegenüber Kontrolle betrug die Wachstumsschätzung für Aufblühen d = 0,31, p = 0,05.",limitation:"Teilnehmerzahlen unterscheiden sich: 473 im Abstract, 472 in den randomisierten Gruppen, 464 in den Wachstumsanalysen. Konfidenzintervall und Vorregistrierung wurden nicht bestätigt. ODAs Version mit einer Handlung unterscheidet sich vom Versuch und verspricht keinen Nutzen für alle."},{id:"F19",title:"Wang und andere · 2021 · Hindernisbezogene Pläne und Ziele",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 Artikel mit 24 unabhängigen Effekten und 15.907 Personen zeigten: Mentales Kontrastieren mit Wenn-dann-Plänen half im Durchschnitt beim Erreichen von Zielen. Effektgröße g = 0,336, 95%-Konfidenzintervall [0,229; 0,443].",limitation:"Ziele und Anwendung variierten. Die Korrektur für Publikationsverzerrung verringerte die Schätzung. Das bestätigt weder aufrichtige Absicht allein noch Gebet als Ursache von Erfolg, eine glaubensbezogene Checkliste oder zehn Minuten als optimale Vorbereitungsdauer."},{id:"F20",title:"NIMH · 2026 · Für deine psychische Gesundheit sorgen",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Anhaltende Belastung und Schwierigkeiten mit üblichen Alltagsaufgaben sprechen für fachliche Unterstützung. In einer Krise brauchst du sofort Hilfe.",limitation:"Öffentliche Orientierung, keine Diagnose oder Erklärung durch eine spirituelle Ursache. Du musst weder zwei Wochen warten noch einen Kurs abschließen, bevor du Hilfe suchst. Gebet und spirituelle Beratung ersetzen keine Gesundheitsversorgung."},{id:"faith-kindness",title:"Curry und andere · 2018 · Freundlichkeit und Wohlbefinden der helfenden Person",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"In 27 Studien mit 4.045 Personen zeigten freundliche Handlungen einen bescheidenen durchschnittlichen Nutzen für das Wohlbefinden der helfenden Person: δ = 0,28, 95%-Konfidenzintervall [0,16; 0,41].",limitation:"Unterschiedliche, überwiegend nichtklinische Studien. Keine Garantie für jede helfende oder empfangende Person, kein Behandlungseffekt und kein Maß religiösen Lohns. Keine Bestätigung unbegrenzter Selbstaufopferung. Nicht entdeckte Verzerrungen oder Einflussfaktoren sind damit nicht ausgeschlossen."}],i=[{schemaVersion:2,revision:2,id:"faith-1",courseId:"faith",locale:"de",title:"Die gute Absicht wartet immer noch",goal:"Führe einen nützlichen Teil einer Zusage aus, die den Wert ausdrückt, den du gewählt hast.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Du wolltest helfen. Mach heute einen nützlichen Teil deiner Zusage wahr.",reason:{id:"faith-1-purpose-cost",label:"Welchen Teil würdest du auch ohne Lob wählen?",kind:"text",maxLength:160,optional:!0,suggestions:["Meine alltägliche Zusage einhalten","Innerhalb meiner tatsächlichen Grenzen helfen","Nach meinem gewählten Wert handeln"]},why:{id:"faith-1-why",label:"Welchen Teil würdest du auch ohne Lob wählen?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Bukhari spricht im ersten Hadith über Taten und Absichten. Umar überliefert die Lehre des Propheten. Diese Übung für Alltagsaufgaben ist ODAs Auslegung. Wähle eine Zusage. Überlege, wozu du sie erfüllen willst und welche nützliche Handlung dazu passt. Die App soll deine Motive nicht beurteilen.","Du kannst helfen wollen und zugleich Anerkennung suchen. Du musst hier keine reine Absicht beweisen. Entscheide, wozu du beitragen willst. Führe dann einen vereinbarten Teil aus. Ist die Handlung nicht möglich, bleibt Vorbereitung Vorbereitung. Behalte spirituelle Gedanken auf Wunsch außerhalb von ODA. Freiwillige Antworten werden in Lektion oder Plan gespeichert. Für das Teilen mit dem Coach gelten eigene Zustimmungen."],example:{title:"Yusuf hält eine kleine Zusage ein",text:"Yusuf hat seiner Nachbarin eine einfache Handyanleitung versprochen. Beim Mittagessen will er helfen und auch verlässlich wirken. Er entscheidet sich fürs Helfen und schickt die vereinbarten Schritte für einen Anruf. Die Nachbarin antwortet an diesem Nachmittag nicht. Yusuf hält die versendete Nachricht fest. Seine Motive bleiben privat. Ob die Anleitung geholfen hat, ist weiterhin unbekannt."}},move:{invitation:"Erfülle einen nützlichen Teil deiner Zusage. Passe das Beispiel an eure tatsächliche Vereinbarung an.",instructions:["Benenne Zusage, sicheren Empfänger, Kontaktweg und Startsignal. Du kannst deinen Plan privat halten.","Nutze eure bestehende Vereinbarung. Senden ist die Handlung, nur Verfassen ist Vorbereitung."],prompts:[],suggestions:{action:["Beispiel: Maja den vereinbarten Link zur Handyeinstellung schicken","Die Yusuf versprochenen beiden Tassen abwaschen","Sven den vereinbarten Weg zum Termin schicken"],minimum:["Maja diesen vereinbarten Link zur Handyeinstellung schicken","Beide vereinbarten Tassen abwaschen","Die vereinbarte Wegbeschreibung zur Bushaltestelle schicken"],cue:["Nachdem ich mit dem Mittagessen fertig bin","Nachdem unser gemeinsames Essen vorbei ist","Wenn Svens Erinnerung an den Termin kommt"],place:["In unserem bisherigen Chat","An unserer für uns zugänglichen Küchenspüle","In unserem bisherigen Nachrichtenverlauf"],minutes:[2,1],fallback:["Bei Nachrichtenproblemen unseren vereinbarten E-Mail-Weg nutzen","Eine andere nützliche, für mich machbare Putzaufgabe vereinbaren","Unseren vereinbarten, für mich zugänglichen Kontaktweg nutzen"],observation:["Link geschickt; Nutzen und Antwort noch unbekannt","Versprochene Aufgabe erledigt, nicht nur vorbereitet","Anleitung geschickt; eine Antwort kann trotzdem ausbleiben"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: Maja den vereinbarten Link zur Handyeinstellung schicken",minimum:"Maja diesen vereinbarten Link zur Handyeinstellung schicken",cue:"Nachdem ich mit dem Mittagessen fertig bin",place:"In unserem bisherigen Chat",fallback:"Bei Nachrichtenproblemen unseren vereinbarten E-Mail-Weg nutzen",observation:"Link geschickt; Nutzen und Antwort noch unbekannt",minutes:2},{action:"Die Yusuf versprochenen beiden Tassen abwaschen",minimum:"Beide vereinbarten Tassen abwaschen",cue:"Nachdem unser gemeinsames Essen vorbei ist",place:"An unserer für uns zugänglichen Küchenspüle",fallback:"Eine andere nützliche, für mich machbare Putzaufgabe vereinbaren",observation:"Versprochene Aufgabe erledigt, nicht nur vorbereitet",minutes:1},{action:"Sven den vereinbarten Weg zum Termin schicken",minimum:"Die vereinbarte Wegbeschreibung zur Bushaltestelle schicken",cue:"Wenn Svens Erinnerung an den Termin kommt",place:"In unserem bisherigen Nachrichtenverlauf",fallback:"Unseren vereinbarten, für mich zugänglichen Kontaktweg nutzen",observation:"Anleitung geschickt; eine Antwort kann trotzdem ausbleiben",minutes:2}]},suggested:{action:"Beispiel: Maja den vereinbarten Link zur Handyeinstellung schicken",minimum:"Maja diesen vereinbarten Link zur Handyeinstellung schicken",minutes:2,cueHint:"Nachdem ich mit dem Mittagessen fertig bin",placeHint:"In unserem bisherigen Chat",obstacleHint:"Beispiel: Ich erkläre meine Motive, statt die Nachricht zu schicken",fallbackHint:"Bei Nachrichtenproblemen unseren vereinbarten E-Mail-Weg nutzen",observationHint:"Link geschickt; Nutzen und Antwort noch unbekannt"},stopRule:"Wähle nur sichere, freiwillige Handlungen, die innerhalb deiner Grenzen liegen.",accessibleAlternative:"Nutze deine übliche Art der Kommunikation. Du kannst den Plan außerhalb von ODA behalten."},result:{question:"Hast du die nützliche Handlung ausgeführt, die du gewählt hast?",observationPrompt:"Was hast du tatsächlich getan, ohne private Motive offenzulegen?"},judgment:{primary:{id:"faith-1-decision",scenario:"Yusuf hat einem Kurskollegen nützliche Notizen versprochen. Sie sind fertig. Er will helfen und Anerkennung bekommen. Das Versenden ist sicher und erwünscht.",question:"Welche Entscheidung erfüllt die vereinbarte Zusage?",options:[{id:"private-reflection",text:"Einen weiteren Tag privat über seine Motive nachdenken, bevor er entscheidet, ob er die fertigen Notizen schickt.",feedback:"Privates Nachdenken kann wertvoll sein. Hier ist die sichere, vereinbarte Hilfe aber bereit. Auf eine reinere Absicht zu warten verzögert sie. Yusuf darf nachdenken, ohne Reinheit zur Voraussetzung fürs Handeln zu machen."},{id:"send-agreed-notes",text:"Sich fürs Helfen entscheiden und die vereinbarten Notizen schicken, ohne Lob zur Bedingung zu machen.",feedback:"So erfüllt er seine gewählte Zusage, obwohl mehrere Motive bestehen. Die Notiz beschreibt verschickte Unterlagen, keine bewiesene Aufrichtigkeit. Ob der Kurskollege antwortet oder davon profitiert, bleibt eine eigene Beobachtung."},{id:"explain-intention",text:"Dem Kurskollegen erst seine Absicht erklären. Die Notizen dann anbieten, nachdem dieser geantwortet hat.",feedback:"Die Erklärung mag ehrlich wirken. Sie verlangt aber, dass der Kurskollege sich vor der vereinbarten Hilfe mit Yusufs Motiven beschäftigt. Yusuf darf seine Gedanken privat halten und die nützlichen Notizen direkt schicken."}],bestOptionId:"send-agreed-notes"}},carry:{takeaway:"Tu etwas Nützliches für dein Anliegen. Deine persönliche Absicht darf bei dir bleiben.",followUp:{questionId:"faith-1-return",question:"Hat die Handlung deinem gewählten Zweck gedient, oder war sie nur Vorbereitung?",observationPrompt:"Was hast du tatsächlich getan, ohne private Motive offenzulegen?",adjustmentPrompt:"Wie passt dein nächster Versuch besser in deinen Alltag?"}},goDeeper:{sections:[{heading:"Religiöse Bedeutung und Aufzeichnung bleiben getrennt",paragraphs:["In Sahih al-Bukhari 1 überliefert Umar ibn al-Khattab die Lehre des Propheten über Taten und Absichten. ODAs Übung fragt, wie ein gewählter Zweck einer alltäglichen Zusage Richtung geben kann. Das ist eine heutige pädagogische Auslegung. Es ist weder der Wortlaut des Hadiths noch eine vollständige Erklärung oder ein religiöses Urteil. [F01] Du darfst privat darüber nachdenken, ohne ein Motiv in die App zu schreiben.","Bukhari 6491 beschreibt beabsichtigte und ausgeführte Taten in einer theologischen Darstellung ihrer Aufzeichnung. Ein Verhaltensprotokoll kann diese Darstellung nicht zu einer Punktzahl für erledigte Aufgaben vereinfachen oder göttlichen Lohn bestimmen. [F02] „Anleitung vorbereitet“ und „vereinbarte Anleitung geschickt“ beschreiben verschiedene Handlungen. Keine davon verrät ODA, wie aufrichtig du warst. Plan, Quizantwort, Übungsserie oder Pause sind keine Grundlage, deinen Glauben zu beurteilen. Ist eine Handlung nicht möglich, darfst du ehrlich Vorbereitung wählen. Wenn es hilft, benenne auch die nächste Gelegenheit, bei der du das Vorbereitete tatsächlich nutzt."]},{heading:"Ein Plan hilft, den Zweck umzusetzen",paragraphs:["Ein Überblick zum Planen von Zielen fasste 21 Artikel mit 24 unabhängigen Effekten zusammen. Einen gewünschten Zustand mit einem echten Hindernis zu vergleichen und eine Handlung dafür zu planen half im Durchschnitt beim Erreichen von Zielen. Die Korrektur für Publikationsverzerrung verringerte den geschätzten Nutzen. Vorgehensweisen und Ziele unterschieden sich. Das ist psychologische Evidenz für ein Planungspaket. Es beweist weder religiösen Lohn noch Gebetswirkung oder die konkrete Checkliste dieses Kurses. [F19]","ODA passt die Idee an: Wähle eine nützliche Handlung, ein erkennbares Startsignal, einen geeigneten Ort und eine Lösung für ein wahrscheinliches Hindernis. Wähle eine alltägliche Zusage, die dir diese Woche wichtig ist. Bleib im Kurs dabei. Spätere Lektionen helfen dir bei Vorbereitung, Anerkennen tatsächlicher Hilfe oder zusätzlicher Unterstützung, wenn du das brauchst. Mehrere Motive verpflichten dich nicht, sie offenzulegen. Behalte deinen Plan auf Wunsch privat. Dann kann ODA deine Entscheidung zum Rückblick erinnern, aber keine Handlungsdetails abrufen, die du nie eingegeben hast."]}],sourceIds:["F01","F02","F19"]}},{schemaVersion:2,revision:2,id:"faith-2",courseId:"faith",locale:"de",title:"Noch ein Check? Erfülle deinen Teil der Zusage.",goal:"Erfülle deine vorbereitete Zusage. Fehlt etwas, bereite es vor und lege fest, wann du aufhörst.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Alles bereit, aber du prüfst weiter? Noch ein Check braucht eine echte Lücke.",reason:{id:"faith-2-actual-gap-cost",label:"Was fehlt noch? Oder was würde ein weiterer Check nur verschieben?",kind:"text",maxLength:160,optional:!0,suggestions:["Alles bereit: meine gespeicherte Zusage erfüllen","Information fehlt: nur diese Lücke prüfen","Zeit unbestätigt: um eine Vereinbarung bitten"]},why:{id:"faith-2-why",label:"Welche Vorbereitung reicht für deinen nächsten tatsächlichen Schritt?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Beratung, Entschluss und Vertrauen kommen in Al Imran 3:159 gemeinsam vor. ODA nutzt das als Anregung, über Einsatz und Vertrauen im Alltag nachzudenken. Daraus folgt keine Regel, dass Vertrauen erst nach Vorbereitung beginnt. Auch mit ernsthaftem Einsatz bleibt ein unsicheres Ergebnis unsicher.","Komm auf deine Zusage zurück. Fehlt wirklich etwas, wähle eine nützliche Vorbereitung und lege fest, wann du aufhörst. Hast du alles Nötige, handle, statt nochmals zu prüfen. Beurteile Vorbereitung danach, was fertig ist, nicht danach, ob du dich beruhigt fühlst. Gebet darf deine Wahl privat begleiten. Es ist weder vorgeschriebene Methode noch versprochenes Ergebnis."],example:{title:"Yusuf prüft einmal",text:"Yusufs Nachbarin fragt, ob die Handyanleitung für ihr Modell passt. Am Küchentisch prüft und korrigiert er einen nötigen Schritt. Nach dem geplanten Test hört er auf und bietet für morgen ein sicheres Telefonat an. Sie hat noch nicht zugesagt. Yusuf hält die erledigte Vorbereitung fest. Sein Gebet bleibt privat. Das spätere Telefonat vermerkt er nicht als erledigt."}},move:{invitation:"Bereit? Erfülle deine Zusage. Fehlt etwas, begrenze die Vorbereitung darauf.",instructions:["Konkrete Lücke? Wähle „Diesen Schritt anpassen“, „Vorbereitung“. Behalte deine Zusage.","Nenne deine Grenze. Wann nutzt du das Vorbereitete? Unbestätigt? Notiere das.","Speichern plant nur Vorbereitung. Bestätige Datum und Startsignal zum Anwenden gesondert im Kalender."],prompts:[{id:"faith-2-gap-next-use",label:"Was fehlt? Welche Grenze setzt du? Ist das spätere Anwenden bestätigt?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Beispiel: Majas Kontakteinstellung einmal testen. Telefonat unbestätigt. Datum/Startsignal außerhalb von ODA oder unter „Handlung“ notieren."}],suggestions:{action:["Beispiel: Maja den fertigen Link zur Handyeinstellung schicken","Maja wie vereinbart die Handyanleitung telefonisch erklären"],minimum:["Maja diesen fertigen, vereinbarten Link schicken","Den vereinbarten ersten Telefonkontakt erklären"],cue:["Nachdem ich mit dem Mittagessen fertig bin","Wenn unser bestätigtes Telefonat um 18 Uhr beginnt"],place:["In unserem bisherigen Chat","In unserem bisherigen, für uns zugänglichen Telefonat"],minutes:[2,5],fallback:["Bei Nachrichtenproblemen unseren vereinbarten E-Mail-Weg nutzen","Kann Maja nicht, nach einem anderen Datum fragen"],observation:["Link geschickt; Wiederholung oder neue Information","Telefonat versucht; weiterer Termin vielleicht unbestätigt"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: Maja den fertigen Link zur Handyeinstellung schicken",minimum:"Maja diesen fertigen, vereinbarten Link schicken",cue:"Nachdem ich mit dem Mittagessen fertig bin",place:"In unserem bisherigen Chat",fallback:"Bei Nachrichtenproblemen unseren vereinbarten E-Mail-Weg nutzen",observation:"Link geschickt; Wiederholung oder neue Information",minutes:2},{action:"Maja wie vereinbart die Handyanleitung telefonisch erklären",minimum:"Den vereinbarten ersten Telefonkontakt erklären",cue:"Wenn unser bestätigtes Telefonat um 18 Uhr beginnt",place:"In unserem bisherigen, für uns zugänglichen Telefonat",fallback:"Kann Maja nicht, nach einem anderen Datum fragen",observation:"Telefonat versucht; weiterer Termin vielleicht unbestätigt",minutes:5}]},suggested:{action:"Beispiel: Maja den fertigen Link zur Handyeinstellung schicken",minimum:"Maja diesen fertigen, vereinbarten Link schicken",minutes:2,cueHint:"Nachdem ich mit dem Mittagessen fertig bin",placeHint:"In unserem bisherigen Chat",obstacleHint:"Beispiel: Es fehlt keine Information. Ich möchte Gewissheit",fallbackHint:"Bei Nachrichtenproblemen unseren vereinbarten E-Mail-Weg nutzen",observationHint:"Link geschickt; Wiederholung oder neue Information"},stopRule:"Hör an deiner Grenze auf. Beeinträchtigt Belastung deinen Alltag, such jetzt fachliche Hilfe.",accessibleAlternative:"Nutze zugängliche Übungsmöglichkeiten oder Beratung. Gebet und Schreiben bleiben freiwillig."},result:{question:"Hast du genau deine gespeicherte Handlung ausgeführt?",observationPrompt:"Was hast du ausgeführt, was vorbereitet? Ist die spätere Nutzung noch unbestätigt?"},judgment:{primary:{id:"faith-2-decision",scenario:"Yusuf hat die Anleitung getestet und die Telefonzeit bestätigt. Er prüft dieselben Schritte immer wieder. Er sorgt sich weiterhin, dass das Telefonat schlecht laufen könnte.",question:"Welche Entscheidung passt zu dem, was noch fehlt?",options:[{id:"longer-test",text:"Dieselbe Anleitung noch einmal vollständig testen, um sich vor dem geplanten Telefonat sicherer zu fühlen.",feedback:"Ein weiterer Test kann bei einer konkreten Lücke helfen. Hier sind Schritte geprüft und Zeit bestätigt. Mehr Wiederholung garantiert kein gelungenes Telefonat. Behalte die vereinbarte Gelegenheit bei, um die Zusage tatsächlich auszuführen."},{id:"cancel-call",text:"Das morgige Telefonat durch eine weitere schriftliche Anleitung ersetzen, damit er sich ohne direktes Gespräch vorbereiten kann.",feedback:"Eine schriftliche Anleitung kann bei Bedarf den Zugang erleichtern. Hier ist das vereinbarte Telefonat vorbereitet und passend. Nur für mehr Gewissheit die Form zu wechseln umgeht den nächsten Schritt, der schon möglich ist."},{id:"keep-opportunity",text:"Diese Vorbereitung beenden, das vereinbarte Telefonat morgen beibehalten und zulassen, dass sein Ergebnis unsicher bleibt.",feedback:"So behält er die nützliche Vorbereitung und ihre Grenze bei, ohne Gewissheit vorzutäuschen. Yusuf hält fest, was bereit ist. Er versucht das Telefonat zur vereinbarten Zeit. Weniger Angst ist keine Bedingung fürs Erledigen."}],bestOptionId:"keep-opportunity"}},carry:{takeaway:"Erledige deinen möglichen Teil. Lass das Ergebnis offen und die nächste Gelegenheit klar.",followUp:{questionId:"faith-2-gap-execution-return",question:"Hast du die gespeicherte Handlung ausgeführt? Diente die Vorbereitung einer tatsächlich noch offenen Lücke?",observationPrompt:"Was hast du ausgeführt, was vorbereitet? Ist die spätere Nutzung noch unbestätigt?",adjustmentPrompt:"Wie passt dein nächster Versuch besser in deinen Alltag?"}},goDeeper:{sections:[{heading:"Einsatz und Vertrauen ohne starre Reihenfolge",paragraphs:["Al Imran 3:159 verbindet Beratung, Entschluss und Vertrauen. ODA leitet daraus eine freiwillige Anregung für den Alltag ab: Frage nach einer echten Lücke, entscheide überlegt und erledige den Teil, der dir möglich ist. Das ist eine Auslegung für die praktische Anwendung. Sie besagt nicht, dass Vertrauen fehlt, bis eine Vorbereitungsliste abgearbeitet ist. Sie verspricht auch nicht, dass ein gewünschtes Ergebnis danach eintreten muss. [F03]","Diese Übung schreibt dir nicht vor, wie du vertrauen sollst. Die Grenze betrifft deine alltägliche Vorbereitung. Du entscheidest, ob dir dieses freiwillige religiöse Nachdenken bei der praktischen Wahl hilft. Nützliche Vorbereitung kann eine Frage, ein geprüfter Schritt oder eine Probe sein. Hör an deiner gewählten Grenze auf. Bestätige Datum und Startsignal fürs Ausführen getrennt in deinem Kalender. Fehlt die Bestätigung, halte das fest. Das Speichern plant die Vorbereitung und ihren Rückblick am nächsten Tag, nicht das spätere Telefonat. Ein geplantes Telefonat ist kein erledigtes Telefonat. Freiwilliges Gebet kann beide Phasen begleiten und bleibt privat. Es gibt keine vorgeschriebene Gebetsmenge oder Glaubenspunktzahl."]},{heading:"Ausreichende Vorbereitung ist eine praktische Entscheidung",paragraphs:["Forschung zu hindernisbezogenen Plänen unterstützt im Durchschnitt konkrete Pläne zum Erreichen von Zielen in unterschiedlichen Umgebungen. Sie prüft nicht diesen religiösen Rahmen. Sie belegt weder zwei Minuten als optimale Dauer noch bessere Ergebnisse durch wiederholte Checks zur Beruhigung. [F19] ODAs Grenze ist eine Anpassung, damit Vorbereitung an einem echten Bedarf bleibt. Fehlt Information, suche sie. Ist der nächste Schritt unsicher oder für dich nicht zugänglich, wähle einen anderen Weg oder passende Unterstützung.","Bei anhaltender Belastung, gestörtem Schlaf oder Schwierigkeiten mit üblichen Alltagsaufgaben ist fachliche Unterstützung neben religiösem Nachdenken möglich. NIMHs Orientierung belegt keine spirituelle Ursache und verlangt nicht, zwei Wochen auf Hilfe zu warten. In einer Krise brauchst du sofort Unterstützung statt einer weiteren Vorbereitungsübung. [F20] Eine sachkundige religiöse Beratung darf freiwillig bei spirituellen Fragen helfen. Sie ersetzt keine Gesundheitsversorgung. Halte fest, welche Vorbereitung du tatsächlich gemacht hast. Emotionale Gewissheit und äußerer Erfolg sind keine Bedingungen dafür, sie als erledigt zu beschreiben."]}],sourceIds:["F03","F19","F20"]}},{schemaVersion:2,revision:2,id:"faith-3",courseId:"faith",locale:"de",title:"Jemand hat geholfen. Sag, was es war.",goal:"Schreibe einen ehrlichen Dank für Hilfe bei deiner Zusage. Ob du ihn teilst, entscheidest du.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Hilfe trotz Streit? Du kannst danken, ohne so zu tun, als wäre alles gut.",reason:{id:"faith-3-acknowledgment-tradeoff",label:"Was macht Danken schwierig? Welche Handlung kannst du ehrlich anerkennen?",kind:"text",maxLength:160,optional:!0,suggestions:["Hilfe anerkennen, den Streit offenlassen","Kontakt sicher und freiwillig halten","Ohne erhaltene Hilfe meine Zusage weiterverfolgen"]},why:{id:"faith-3-why",label:"Wessen sichere Unterstützung hat dir bei deiner gewählten Zusage geholfen?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Die Lehre in Abu Dawud 4811 verbindet Dank an Menschen mit Dank an Allah. Die kurze Notiz ist ODAs Anpassung. Benenne einen echten Beitrag zu deiner Zusage. Du musst dafür nicht die ganze Beziehung gut finden.","Forschung findet einen kleinen durchschnittlichen Nutzen ausgedrückter Dankbarkeit für das Wohlbefinden. Die Ergebnisse variieren. Sie belegen keine Gleichwertigkeit mit Therapie und verlangen kein besseres Gefühl. Wähle eine passende Notiz. Eine offene Zusage bleibt davon getrennt. Benenne für dich die Handlung und ihren Nutzen. Schreiben und freiwilliges Senden sind verschiedene Schritte. Gab es keine Hilfe, verfolge stattdessen deine Zusage weiter."],example:{title:"Yusufs ehrliche Notiz",text:"Yusufs Schwester hat ihm eine verständliche Handyanleitung geliehen. In einer anderen Familienfrage sind sie weiter uneins. Er schreibt privat: „Deine Anleitung half mir, unserer Nachbarin den ersten Anruf zu erklären.“ An diesem Abend behält er die Notiz, weil er wegen des Kontakts unsicher ist. Der Streit bleibt. Er vermerkt nur eine geschriebene Notiz, ohne ihren Inhalt in ODA zu speichern."}},move:{invitation:"Benenne die tatsächliche Hilfe. Diese passende Notiz bleibt getrennt von deiner Zusage.",instructions:["Wähle „Eine eigene verwandte Handlung planen“. Eine offene Zusage bleibt davon getrennt.","Benenne beobachtete Handlung und Nutzen. Teile sie nur bei sicherem, erwünschtem Kontakt.","Keine Hilfe erhalten? Verfolge deine Zusage weiter. Unter Druck benenne nur die Hilfe oder pausiere."],prompts:[],suggestions:{action:["Beispiel: Maja privat für ihre Anleitung danken","Sven privat für die Vertretung am Dienstag danken"],minimum:["Schreiben: Majas Anleitung half, einen Telefonkontakt zu erklären","Schreiben: Svens Vertretung ermöglichte meinen vereinbarten Termin"],cue:["Nachdem ich mit dem Mittagessen fertig bin","Nachdem die vereinbarte Schicht endet"],place:["In meinen eigenen privaten Notizen","An einem ruhigen, zugänglichen Ort für mich"],minutes:[2,1],fallback:["Nur Handlung und Nutzen für mich aussprechen","Nur diese Schicht benennen; Streit bleibt offen"],observation:["Notiz geschrieben oder gesprochen; ursprüngliche Zusage bleibt offen","Dank ausgedrückt; ursprüngliche Zusage getrennt festhalten"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: Maja privat für ihre Anleitung danken",minimum:"Schreiben: Majas Anleitung half, einen Telefonkontakt zu erklären",cue:"Nachdem ich mit dem Mittagessen fertig bin",place:"In meinen eigenen privaten Notizen",fallback:"Nur Handlung und Nutzen für mich aussprechen",observation:"Notiz geschrieben oder gesprochen; ursprüngliche Zusage bleibt offen",minutes:2},{action:"Sven privat für die Vertretung am Dienstag danken",minimum:"Schreiben: Svens Vertretung ermöglichte meinen vereinbarten Termin",cue:"Nachdem die vereinbarte Schicht endet",place:"An einem ruhigen, zugänglichen Ort für mich",fallback:"Nur diese Schicht benennen; Streit bleibt offen",observation:"Dank ausgedrückt; ursprüngliche Zusage getrennt festhalten",minutes:1}]},suggested:{action:"Beispiel: Maja privat für ihre Anleitung danken",minimum:"Schreiben: Majas Anleitung half, einen Telefonkontakt zu erklären",minutes:2,cueHint:"Nachdem ich mit dem Mittagessen fertig bin",placeHint:"In meinen eigenen privaten Notizen",obstacleHint:"Beispiel: Ich fühle mich gedrängt, unseren Streit beizulegen",fallbackHint:"Nur Handlung und Nutzen für mich aussprechen",observationHint:"Notiz geschrieben oder gesprochen; ursprüngliche Zusage bleibt offen"},stopRule:"Suche für Dank keinen Kontakt, der dich gefährdet. Übergehe dafür auch keinen erlittenen Schaden.",accessibleAlternative:"Sprich oder tippe privat. Empfänger und Inhalt darfst du für dich behalten."},result:{question:"Hast du deinen gewählten Dank tatsächlich ausgedrückt?",observationPrompt:"Geschrieben, privat ausgesprochen oder freiwillig geteilt: Was hast du getan?"},judgment:{primary:{id:"faith-3-honest-acknowledgment-decision",scenario:"Sven übernahm Yusufs Dienstagsschicht. Yusuf konnte zu einem Gesundheitstermin. Ein anderer Streit bleibt offen. Der Kontakt ist sicher. Sven hat gesagt, dass er nächste Woche nicht vertreten kann und jetzt keine weitere Bitte möchte. Yusuf will die Dienstagshilfe anerkennen.",question:"Welcher Dank passt zu den Fakten und Svens Grenze?",options:[{id:"faith-3-misstated-help",text:"Sven danken, dass er den Gesundheitstermin organisiert und die Dienstagsschicht übernommen hat, damit Yusuf hingehen konnte.",feedback:"Sven hat die Schicht übernommen. Das Beispiel sagt nicht, dass er den Termin organisiert hat. Beschränke den Dank auf die beobachtete Handlung und ihren Nutzen. Ehrlicher Dank kann neben einem ungelösten Streit bestehen."},{id:"faith-3-specific-thanks",text:"Sven für die Dienstagsschicht danken und den dadurch möglichen Gesundheitstermin nennen. Den anderen Streit offenlassen.",feedback:"So benennt er beobachtete Handlung und Nutzen und respektiert die aktuelle Grenze. Gemischte Gefühle dürfen bleiben. Yusuf kann die Notiz privat behalten oder freiwillig teilen. Weder seine ursprüngliche Zusage noch der Streit sind damit erledigt."},{id:"faith-3-new-request",text:"Sven für die Dienstagsschicht danken und erklären, warum eine weitere Vertretung nächste Woche ebenfalls helfen würde.",feedback:"Dank und eine offene Bitte können zusammenpassen. Hier hat Sven jetzt ausdrücklich keine weitere Bitte gewünscht. Eine hinzuzufügen missachtet seine Grenze. Benenne die Dienstagshilfe und suche künftige Vertretung anderswo."}],bestOptionId:"faith-3-specific-thanks"}},carry:{takeaway:"Benenne die tatsächliche Hilfe. Eine Notiz erfüllt deine ursprüngliche Zusage nicht und löst nicht jede Verletzung.",followUp:{questionId:"faith-3-related-note-return",question:"War dein Dank ehrlich und sicher? Blieb deine ursprüngliche Zusage getrennt davon festgehalten?",observationPrompt:"Wurde die Notiz geschrieben, gesprochen oder geteilt? Welche ursprüngliche Handlung bleibt offen?",adjustmentPrompt:"Wie passt dein nächster Versuch besser in deinen Alltag?"}},goDeeper:{sections:[{heading:"Eine konkrete Dankesnotiz ist eine Anpassung",paragraphs:["Abu Dawud 4811 verbindet Dank an Menschen mit Dank an Allah. Der Eintrag nennt Abu Hurayrah als Überlieferer und zeigt al-Albanis Einstufung „sahih“. ODAs praktische Notiz ist eine heutige Anpassung. Sie ist weder der Wortlaut der Quelle noch eine neue religiöse Beglaubigung. [F07] Du darfst einen Beitrag anerkennen, ohne private religiöse Gedanken zu teilen oder die App zum Richter über deine Dankbarkeit zu machen.","Die Vorlage benennt, was jemand getan hat und welchen Nutzen du beobachtet hast. Sie hilft beim Schreiben. Sie ist kein bestätigter wissenschaftlicher Beleg, dass konkreter Dank allgemeinem Dank überlegen ist. Die Hilfe einer sicheren Person kann echt sein, während Streit oder Verletzung ebenfalls bestehen bleiben. Halte diese Fakten auseinander. Privat zu schreiben und eine Nachricht zu senden sind verschiedene Handlungen. Vermerke, was du tatsächlich gewählt hast. Eine private Notiz ist keine übermittelte Dankbarkeitsübung. Eine unbeantwortete Nachricht hebt die Handlung, die du ausgeführt hast, nicht auf."]},{heading:"Kleine durchschnittliche Wirkung, keine Gleichwertigkeit mit Therapie",paragraphs:["Der Überblick von 2023 zu ausgedrückter Dankbarkeit enthielt 23 Studien und 25 Stichproben. Gegenüber neutralen Bedingungen war die durchschnittliche Wirkung auf Wohlbefinden klein: g = 0,22, mit einem 95%-Konfidenzintervall von 0,11 bis 0,33. Gegenüber anderen Aktivitäten für Wohlbefinden enthielt das Intervall für den Unterschied null. Diese Aktivitäten waren nicht unbedingt etablierte klinische Behandlungen. Eine statistisch nicht signifikante Überlegenheitsprüfung belegt keine Gleichwertigkeit mit Therapie. Die widersprüchlichen Teilnehmerzahlen des Artikels bleiben ungenutzt. [F14]","Ein größerer Überblick von 2025 zu Dankbarkeit fand ebenfalls einen kleinen durchschnittlichen Nutzen. Sein Vorhersageintervall für eine künftige Studie enthielt aber null. Ergebnisse variierten nach Verfahren und Umgebung. [F15] Keiner der beiden Überblicke beweist eine religiöse Lehre, garantiert persönlichen Nutzen oder bestätigt dieses Format mit einem privaten Satz. Du darfst die Handlung abschließen, ohne dich positiv zu fühlen. Nutze die Notiz, wenn sie deiner gewählten Beziehung oder Lebensrichtung dient. Ändere oder beende die Übung, wenn sie nicht hilft oder sich erzwungen anfühlt."]}],sourceIds:["F07","F14","F15"]}},{schemaVersion:2,revision:2,id:"faith-4",courseId:"faith",locale:"de",title:"Alles allein tragen? Bitte um etwas Konkretes.",goal:"Bitte sicher um konkrete Unterstützung bei der Versorgung. Wähle einen Ersatz, falls Hilfe ausbleibt.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Trägst du alles allein? Bitte konkret um Unterstützung bei der Versorgung. Dein Glaube wird hier nicht bewertet.",reason:{id:"faith-4-request-boundary-cost",label:"Was macht eine sichere Bitte schwierig? Welche Grenze würde sie möglich machen?",kind:"text",maxLength:160,optional:!0,suggestions:["Um Hilfe bei einer bestimmten Aufgabe bitten","Weniger private Einzelheiten teilen","Hilfe nicht erst verdienen müssen"]},why:{id:"faith-4-why",label:"Welche Versorgung würde deine bisherige Zusage sicherer machen?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Al-Sharhs Verse über Erleichterung neben Schwierigkeiten geben religiöse Hoffnung, keine Frist. Schau auf den nächsten überschaubaren Moment. Versorgung darf deine ganze wertvolle Handlung sein. Eine Bitte um Unterstützung bleibt getrennt von deiner offenen Zusage und erfüllt sie nicht.","Forschung zu religiöser Bewältigung zeigt Zusammenhänge. Sie beweist weder, dass spirituelle Praxis Erleichterung verursacht, noch dass Schwierigkeiten schwachen Glauben bedeuten. Bitte eine sichere Person oder Fachstelle um etwas Konkretes. Kann sie nicht helfen, nutze eine passende Alternative. Fragen ist deine Handlung, Verfügbarkeit ein Ergebnis. Private Zweifel und Einzelheiten deines Gebets gehören in keine Punktzahl."],example:{title:"Yusuf fragt anderswo nach",text:"Nach der Pflege ist Yusuf erschöpft. Das vereinbarte Telefonat mit der Nachbarin schafft er heute nicht. Er bittet seinen Bruder um eine Hausarbeit. Der kann nicht. Yusuf fragt einen anderen vertrauten Verwandten und bietet der Nachbarin ein späteres Telefonat an. Hilfe bleibt unbestätigt. Er vermerkt seine Bitte und nutzt mögliche Erholung, ohne seinen Glauben zu beurteilen."}},move:{invitation:"Für alltägliche Unterstützung: Benenne eine sichere, konkrete Bitte.",instructions:["Bei Dringendem hol sofort Krisenhilfe oder Nothilfe, bevor du alltägliche Versuche planst.","Wähle „Eine eigene verwandte Handlung planen“. Benenne Hilfe, Empfänger, Kontaktweg und Zeit.","Bei Absage wähle verfügbare Dienste oder sichere Versorgung. Deine offene Zusage bleibt getrennt."],prompts:[],suggestions:{action:["Beispiel: Maja abends per Nachricht um Abwaschhilfe bitten","Meine Praxis nach verfügbaren Terminen fragen"],minimum:["Maja bitten, um 19 Uhr abzuwaschen","Die Praxis um einen passenden Termin bitten"],cue:["Nach der vereinbarten Pflegeübergabe um 18 Uhr","Wenn die Telefonsprechzeit der Praxis beginnt"],place:["In unserem bisherigen Chat","An meinem zugänglichen, ungestörten Platz zum Telefonieren"],minutes:[2,5],fallback:["Bei Absage unwichtigen Abwasch stehenlassen und ausruhen","Den zugänglichen Buchungsweg meiner Praxis nutzen"],observation:["Bitte geschickt; erhaltene Hilfe gesondert festhalten","Kontakt hergestellt; Termin vielleicht noch unbestätigt"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: Maja abends per Nachricht um Abwaschhilfe bitten",minimum:"Maja bitten, um 19 Uhr abzuwaschen",cue:"Nach der vereinbarten Pflegeübergabe um 18 Uhr",place:"In unserem bisherigen Chat",fallback:"Bei Absage unwichtigen Abwasch stehenlassen und ausruhen",observation:"Bitte geschickt; erhaltene Hilfe gesondert festhalten",minutes:2,kind:"support"},{action:"Meine Praxis nach verfügbaren Terminen fragen",minimum:"Die Praxis um einen passenden Termin bitten",cue:"Wenn die Telefonsprechzeit der Praxis beginnt",place:"An meinem zugänglichen, ungestörten Platz zum Telefonieren",fallback:"Den zugänglichen Buchungsweg meiner Praxis nutzen",observation:"Kontakt hergestellt; Termin vielleicht noch unbestätigt",minutes:5,kind:"support"}]},suggested:{kind:"support",action:"Beispiel: Maja abends per Nachricht um Abwaschhilfe bitten",minimum:"Maja bitten, um 19 Uhr abzuwaschen",minutes:2,cueHint:"Nach der vereinbarten Pflegeübergabe um 18 Uhr",placeHint:"In unserem bisherigen Chat",obstacleHint:"Beispiel: Die erste Person kann heute Abend nicht helfen",fallbackHint:"Bei Absage unwichtigen Abwasch stehenlassen und ausruhen",observationHint:"Bitte geschickt; erhaltene Hilfe gesondert festhalten"},stopRule:"In einer Krise oder bei Selbstverletzungsgedanken brauchst du sofort örtliche Krisenhilfe. Bei akuter Gefahr brauchst du Rettungsdienste. Such jetzt Hilfe, bevor du planst.",accessibleAlternative:"Nutze einen für dich zugänglichen Kontaktweg. Gebet ersetzt niemals die Versorgung, die du brauchst."},result:{question:"Hast du die Bitte gestellt oder den Schritt zur Versorgung getan?",observationPrompt:"Welche Versorgung fand statt? Welcher Bedarf bleibt offen?"},judgment:{primary:{id:"faith-4-available-care-decision",scenario:"Leila braucht heute Abend Hilfe beim Umsetzen einer pflegebedürftigen Person. Allein wäre es unsicher. Die Person sitzt gerade sicher. Ein Verwandter hat abgesagt. Der telefonisch erreichbare Pflegedienst kann heute Hilfe organisieren; normale E-Mails werden morgen beantwortet. Während Leila anruft, kann die Person sicher sitzen bleiben.",question:"Welche Bitte trifft den heutigen Bedarf am direktesten?",options:[{id:"faith-4-staffed-line",text:"Beim erreichbaren Pflegedienst anrufen und Hilfe beim heutigen Umsetzen erbitten. Die Person während des Wartens sicher sitzen lassen.",feedback:"So benennt sie die unmittelbar nötige Aufgabe und nutzt einen heute erreichbaren Kontakt. Anrufen ist die Handlung. Bestätigte Hilfe ist gesondert zu prüfen. Ändert sich die Sicherheit beim Warten, suche sofort passende Nothilfe."},{id:"faith-4-general-call",text:"Den erreichbaren Pflegedienst anrufen, die erschöpfende Woche schildern und fragen, welche allgemeinen Pflegehilfen der Dienst anbietet.",feedback:"Die gesamte Belastung zu schildern kann bei fortlaufender Pflege helfen. Das heutige Umsetzen ist konkreter und lässt sich nicht verschieben. Nenne zuerst diese Aufgabe. Besprecht weitere Unterstützung danach, wenn Zeit und Sicherheit es erlauben."},{id:"faith-4-email-and-wait",text:"Die genaue Bitte zum Umsetzen mailen. Die Person sicher sitzen lassen, bis morgen die übliche Antwort kommt.",feedback:"Die E-Mail ist konkret und verhindert unsicheres Umsetzen allein. Ihre Antwortzeit passt aber nicht zum heutigen Bedarf. Ruf jetzt beim erreichbaren Pflegedienst an. Halte fest, ob passende Hilfe tatsächlich bestätigt wurde."}],bestOptionId:"faith-4-staffed-line"}},carry:{takeaway:"Eine klare Bitte ist deine Handlung. Ob Unterstützung verfügbar ist, musst du prüfen und nachverfolgen.",followUp:{questionId:"faith-4-related-support-return",question:"Hast du um Versorgung gebeten? War Hilfe verfügbar, und welcher Bedarf bleibt offen?",observationPrompt:"Welche Bitte oder Versorgung fand statt? Welche ursprüngliche Zusage bleibt gesondert offen?",adjustmentPrompt:"Wie passt dein nächster Versuch besser in deinen Alltag?"}},goDeeper:{sections:[{heading:"Hoffnung kann praktische Versorgung begleiten",paragraphs:["Al-Sharh 94:5–6 bietet durch Erleichterung neben Schwierigkeiten eine religiöse Quelle der Hoffnung. Daraus folgt nicht, dass deine Schwierigkeit heute, an einem gewählten Datum oder genau nach deinen Wünschen endet. ODAs Bitte um Unterstützung ist eine praktische Anpassung. Sie ist kein religiöses Urteil und kein aus den Versen abgeleiteter klinischer Effekt. [F08] Du darfst privat nachdenken oder einfach einen Schritt zur Versorgung wählen.","Ein überschaubarer Moment kann viel kleiner sein als ein Tag. Welches unmittelbare Bedürfnis kannst du benennen? Welche sichere Person oder Stelle könnte helfen? Ist der erste Kontakt nicht verfügbar, sagt das etwas über diesen Kontakt. Es beweist nicht, dass du alles allein tragen sollst. Erholung oder fachliche Versorgung dürfen die ganze wertvolle Handlung sein. Du musst sie dir nicht durch Produktivität verdienen. Eine Grenze kann dich besser schützen als noch eine Zusage. Geduld, Dankbarkeit oder Vergebung dürfen nicht dazu auffordern, Missbrauch oder unsicheren Kontakt auszuhalten."]},{heading:"Forschungskategorien können deinen Glauben nicht beurteilen",paragraphs:["Der Überblick zur religiösen Bewältigung fasste 49 Studien mit 13.512 Personen zusammen. Sie waren überwiegend beobachtend und beruhten auf Selbstauskünften. Die bekannten Werte 0,33 und 0,22 sind zusammengefasste Fisher-z-Werte, keine ursprünglichen Korrelationswerte. Unter den 8.115 Personen mit berichteter Religionszugehörigkeit waren 57% protestantisch und 28% katholisch. Diese Bezugsgruppe umfasst nicht alle Teilnehmenden. Die Zusammenhänge belegen weder Ursache und Wirkung noch Wirksamkeit islamischer Praxis. Forschungskategorien dürfen nicht zum Urteil über deinen Glauben werden. [F13]","NIMH empfiehlt fachliche Hilfe bei anhaltender Belastung und eingeschränktem Alltag. Du darfst früher fragen. Gebet oder freiwillige spirituelle Beratung können Gesundheitsversorgung begleiten, aber nötige Behandlung nicht ersetzen. In einer Krise oder bei Selbstverletzungsgedanken suche sofort örtliche Krisenhilfe. Bei akuter Lebensgefahr brauchst du Rettungsdienste. In den USA kannst du 988 anrufen oder eine Nachricht dorthin senden. Andernorts nutze örtliche Krisen- oder Notdienste. [F20] Warte nicht auf ein Kursergebnis oder eine bestimmte Dauer, bevor du dringende Versorgung suchst."]}],sourceIds:["F08","F13","F20"]}},{schemaVersion:2,revision:2,id:"faith-5",courseId:"faith",locale:"de",title:"Großzügig helfen, ohne eine andere Zusage zu brechen",goal:"Behalte deine nützliche Zusage. Ist Hilfe erwünscht? Plane einen Versuch: Datum und Grenze in Minuten.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Das hilfreiche Telefonat wird immer länger? Wähle Hilfe, die in deine Woche passt.",reason:{id:"faith-5-purpose-cost",label:"Was begrenzt du, damit du diese Zusage tatsächlich einhalten kannst?",kind:"text",maxLength:160,optional:!0,suggestions:["Nur so viel versorgen, wie ich schaffe","Eine andere bestehende Zusage schützen","Nützlich helfen, ohne Dank zu verlangen"]},why:{id:"faith-5-why",label:"Was begrenzt du, damit du diese Zusage tatsächlich einhalten kannst?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Prüfe dieselbe Zusage: Was hast du getan? Was half, was kostete es dich? Behalte nützliche Handlung und nötige Unterstützung. Aischas Überlieferung bei Bukhari betont kleine regelmäßige Taten und Maßhalten. Eine Übungsserie in der App ist kein Maß für Glauben.","Studien zu freundlichen Handlungen finden einen bescheidenen durchschnittlichen Nutzen für die helfende Person. Das garantiert nichts und erlaubt nicht, Grenzen zu übergehen. Behalte deine nützliche Handlung. Prüfe, ob sie erwünscht ist. Schreibe die Grenze in Minuten in „Handlung“ oder „Minimum“. Plane einen Termin. Wiederholung wird nur erwogen. Der morgige Rückblick hilft, eine weitere Gelegenheit mit Datum zu wählen."],example:{title:"Yusuf hört rechtzeitig auf",text:"Yusufs Notizen zeigen: Hilfe bei einem Telefonkontakt nützt, aber abends kollidiert sie mit Pflege. Seine Nachbarin vereinbart nach dem Samstagmittagessen zwei Minuten Austausch per Nachricht. Yusuf schickt die Kontaktanleitung und hört innerhalb von zwei Minuten auf. Eine weitere Frage bleibt. Er vermerkt nützliche Nachricht und eingehaltene Grenze. Nächster Samstag wird erwogen, ist aber noch nicht vereinbart."}},move:{invitation:"Behalte deine nützliche Zusage. Plane eine erwünschte Aufgabe mit Datum und Grenze in Minuten.",instructions:["Behalte die ursprüngliche Zusage. Ändere Umfang oder Zeitpunkt nur durch bewusste Vereinbarung.","Schreibe die Grenze in „Handlung“ oder „Minimum“. Du kannst Einzelheiten außerhalb von ODA behalten."],prompts:[],suggestions:{action:["Beispiel: Maja die Anleitung binnen 2 Minuten schicken","Sven anrufen: ein Telefonkontakt, höchstens 5 Minuten"],minimum:["Vereinbarte Kontaktanleitung binnen 2 Minuten schicken","Einen vereinbarten Kontakt binnen 5 Minuten erklären"],cue:["Nachdem unser vereinbartes Mittagessen vorbei ist","Beim bestätigten Telefonat am Mittwoch um 18 Uhr"],place:["In unserem bisherigen Chat","In unserem bisherigen, für uns zugänglichen Telefonat"],minutes:[2,5],fallback:["Bei mehr Bedarf einen anderen bestätigten Termin anbieten","Bei mehr Bedarf eine getrennte Gelegenheit vereinbaren"],observation:["Vereinbarte Hilfe geschickt, erwünscht; Zwei-Minuten-Grenze eingehalten","Kontakt erklärt, erwünscht; Fünf-Minuten-Grenze eingehalten"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: Maja die Anleitung binnen 2 Minuten schicken",minimum:"Vereinbarte Kontaktanleitung binnen 2 Minuten schicken",cue:"Nachdem unser vereinbartes Mittagessen vorbei ist",place:"In unserem bisherigen Chat",fallback:"Bei mehr Bedarf einen anderen bestätigten Termin anbieten",observation:"Vereinbarte Hilfe geschickt, erwünscht; Zwei-Minuten-Grenze eingehalten",minutes:2},{action:"Sven anrufen: ein Telefonkontakt, höchstens 5 Minuten",minimum:"Einen vereinbarten Kontakt binnen 5 Minuten erklären",cue:"Beim bestätigten Telefonat am Mittwoch um 18 Uhr",place:"In unserem bisherigen, für uns zugänglichen Telefonat",fallback:"Bei mehr Bedarf eine getrennte Gelegenheit vereinbaren",observation:"Kontakt erklärt, erwünscht; Fünf-Minuten-Grenze eingehalten",minutes:5}]},suggested:{action:"Beispiel: Maja die Anleitung binnen 2 Minuten schicken",minimum:"Vereinbarte Kontaktanleitung binnen 2 Minuten schicken",minutes:2,cueHint:"Nachdem unser vereinbartes Mittagessen vorbei ist",placeHint:"In unserem bisherigen Chat",obstacleHint:"Beispiel: Die Bitte wächst über unsere vereinbarten zwei Minuten hinaus",fallbackHint:"Bei mehr Bedarf einen anderen bestätigten Termin anbieten",observationHint:"Vereinbarte Hilfe geschickt, erwünscht; Zwei-Minuten-Grenze eingehalten"},stopRule:"Schütze Gesundheit, Schlaf, Geld und bestehende Zusagen. Unsichere Hilfe oder unsicherer Kontakt sind nicht erforderlich.",accessibleAlternative:"Nutze für dich zugängliche Hilfe oder wähle Erholung, Unterstützung oder eine Grenze."},result:{question:"Hast du deine gewählte Handlung innerhalb der Grenze ausgeführt?",observationPrompt:"Was war nützlich und erwünscht? Hast du deine Grenze eingehalten?"},judgment:{primary:{id:"faith-5-task-boundary-decision",scenario:"Nadjas Nachbarin braucht vor einem Donnerstagstermin Hilfe mit einem Telefonkontakt. Am Mittwoch hat Nadja vor ihrer festen Pflegeaufgabe zehn freie Minuten. Die Nachbarin möchte ein zehnminütiges Telefonat. Nachrichten kann sie schwer lesen. Samstag wären zwanzig Minuten möglich, nach dem Termin.",question:"Welcher Plan passt zur nützlichen Aufgabe und den Grenzen beider?",options:[{id:"faith-5-saturday-call",text:"Das zwanzigminütige Telefonat am Samstag anbieten, damit die Nachbarin mehr Zeit hat, die Handyschritte zu lernen.",feedback:"Samstag schützt Nadjas Pflegeaufgabe und erlaubt mehr Übung. Der Bedarf vor Donnerstag wird aber verfehlt. Nutze das vereinbarte Zeitfenster am Mittwoch für diesen Kontakt. Erwäge Samstag getrennt für spätere Fragen."},{id:"faith-5-text-steps",text:"Die Kontaktschritte am Mittwoch per Nachricht schicken. So bleibt die Pflegeaufgabe geschützt, und die Nachbarin bekommt schriftliche Anweisungen.",feedback:"Eine Nachricht würde Zeit schützen und eine Anleitung zum Nachlesen bieten. Die Nachbarin kann Nachrichten aber schwer lesen. Dieses Format deckt den tatsächlichen Bedarf möglicherweise nicht. Das vereinbarte kurze Telefonat ist hier zugänglich."},{id:"faith-5-ten-minute-call",text:"Am Mittwoch im vereinbarten Zehn-Minuten-Telefonat den einen Kontakt erklären, die Endzeit nennen und vor der Pflegeaufgabe aufhören.",feedback:"So deckt sie den Bedarf vor dem Termin auf erwünschtem, zugänglichem Weg und schützt die Pflege. Vermerke erklärten Kontakt und eingehaltene Grenze. Eine weitere Frage ist eine eigene Gelegenheit, keine Pflicht zum Überziehen."}],bestOptionId:"faith-5-ten-minute-call"}},carry:{takeaway:"Behalte eine erwünschte Handlung, die in deine Woche passt. Nutzen und Aufwand leiten die nächste Wahl.",followUp:{questionId:"faith-5-bounded-occurrence-return",question:"War die vereinbarte Aufgabe nützlich und erwünscht? Schützte ihre Minutengrenze deine anderen Zusagen?",observationPrompt:"Welche nützliche Handlung fand statt? Blieb die Grenze eingehalten, und ist ein weiteres Datum bestätigt?",adjustmentPrompt:"Wie passt dein nächster Versuch besser in deinen Alltag?"}},goDeeper:{sections:[{heading:"Regelmäßig bedeutet nicht unbegrenzt",paragraphs:["Bukhari 6464 betont in einer Aischa zugeschriebenen Überlieferung kleine regelmäßige Taten und Maßhalten. Die vollständige Passage betrifft auch Taten und Heil. ODA nutzt das als freiwillige Anregung, über eine dauerhaft machbare Handlung nachzudenken. Eine Zahl erlaubt der App kein Urteil über religiösen Wert oder Heil. Private Absicht, Gebet, verpasste Gelegenheit oder Übungsserie in der App sind keine Glaubenspunktzahl. [F11]","Schau auf die Handlungen und Unterstützung, die du freiwillig festgehalten hast. Welcher Teil diente wirklich dem Zweck? Wie viel Zeit und Kraft kostete er? Welche andere Zusage verdrängte er? Behalte den nützlichen Teil, statt ein weiteres Ritual hinzuzufügen. Du kannst tägliche oder wöchentliche Wiederholung erwägen. Plane aber einen tatsächlichen Termin. Dieser Plan legt diesen Versuch und seinen Rückblick am nächsten Tag fest, keinen wiederkehrenden Rhythmus. Prüfe, ob die Hilfe erwünscht ist. Nenne eine machbare Grenze und halte sie ein. Übersteigt der Bedarf deine Möglichkeiten, können kleineres Angebot, Weitervermittlung, Erholung oder Aufhören verantwortlicher sein als unbegrenzte Hilfe. Dank und warme Gefühle sind keine Bedingungen fürs Erledigen."]},{heading:"Was die Forschung zu Freundlichkeit tatsächlich prüfte",paragraphs:["Der Überblick von 2018 zu freundlichen Handlungen fasste 27 Studien mit 4.045 Personen zusammen. Solche Handlungen zeigten im Durchschnitt einen bescheidenen Nutzen für das Wohlbefinden der helfenden Person. Stichproben und Vorgehensweisen unterschieden sich. Das garantiert weder Nutzen für jede helfende oder empfangende Person noch misst es religiösen Lohn. Unbegrenzte Selbstaufopferung ist damit nicht bestätigt. Nicht entdeckte Einflussfaktoren oder Publikationsverzerrung beweisen nicht, dass es sie nicht gibt. [F16]","In einem eigenen Versuch sollte die Gruppe für Freundlichkeit gegenüber anderen vier Wochen lang an einem Tag pro Woche drei freundliche Handlungen ausführen. Zwei Wochen danach folgte eine Kontrolle. Es waren keine sechs Wochen vorgeschriebener Handlungen. Teilnehmerzahlen im Abstract und in den randomisierten Gruppen unterschieden sich. Die hauptsächlichen Wachstumsanalysen nutzten eine kleinere Gruppe. [F18] ODAs Plan mit einer Handlung innerhalb deiner Möglichkeiten ist eine andere Anpassung. Plane die nächste tatsächliche Gelegenheit nur, wenn sie weiter passt. Morgen prüfst du, ob die Hilfe nützte, erwünscht war und welchen Aufwand sie verlangte. Du musst weder heute wiederholen noch eine religiöse Übungsserie einhalten."]}],sourceIds:["F11","F16","F18"]}}];function t(e,r,l){const a=e.judgment.primary,n=[...a.options],h=n.findIndex(s=>s.id===a.bestOptionId);return[n[r],n[h]]=[n[h],n[r]],{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Halte fest, was tatsächlich passiert ist. Schau morgen auf denselben Versuch zurück."],reflection:e.direction.reason.label,question:`${a.scenario} ${a.question}`,options:n.map(s=>s.text),correct:r,feedback:n[r].feedback,takeaway:e.carry.takeaway,sources:e.id==="faith-5"?[...e.goDeeper.sourceIds,"faith-kindness"]:e.goDeeper.sourceIds,photo:l}}const d={id:"faith",title:"Du wolltest helfen. Lass deinen Glauben dein Handeln leiten.",subtitle:"5 freiwillige Lektionen. Erfülle eine sinnvolle Zusage, behalte deine Gedanken privat und schaffe Raum für Versorgung und Grenzen.",description:"Verbinde freiwilliges islamisches Nachdenken mit einer gewählten Alltagshandlung. Passe sie durch Vorbereitung, ehrlichen Dank, Unterstützung und klare Grenzen an.",scope:"Islamische Anregungen zum Nachdenken und freiwillige Alltagsübungen. Religiöse Quellen und psychologische Forschung werden getrennt gezeigt. Angst oder Schwierigkeiten gelten nicht als Glaubensmangel. Der Kurs ist kein religiöses Urteil und ersetzt keine psychische Gesundheitsversorgung. In einer Krise oder bei Gedanken, dir selbst zu schaden, kontaktiere sofort deine örtliche Notrufnummer.",outcome:"Eine ausprobierte oder pausierte Zusage, private Gedanken und ein nächster Schritt oder Unterstützung mit Datum.",photo:{id:"1767396024869-756a346dc39d",alt:"Ein Moscheehof mit Bogentüren und Bäumen"},lang:"de",lessons:[t(i[0],1,{id:"1778616364918-34490657598f",alt:"Ein Mann hält Gebetsperlen"}),t(i[1],2,{id:"1590682680695-43b964a3ae17",alt:"Hände pflanzen einen Setzling in Erde"}),t(i[2],1,{id:"1634906346143-aacbc4c02fec",alt:"Eine Dankesnotiz neben einer Brille auf einem Tisch"}),t(i[3],0,{id:"1570739260082-39a84dae80c8",alt:"Eine leuchtende Laterne auf einem Holztisch"}),t(i[4],2,{id:"1710092784814-4a6f158913b8",alt:"Eine Frau reicht einer anderen Frau einen Teller mit Essen"})]},g=Object.freeze(Object.defineProperty({__proto__:null,COURSE:d,LESSONS_V2:i,SOURCES:u},Symbol.toStringTag,{value:"Module"}));export{g as f};
